<script lang="ts">
 import {onMount} from 'svelte';import {Button} from '$lib/components/ui/button';import {Upload,FileVideo,CheckCircle2} from '@lucide/svelte';import {request} from '../api';
 let {user}:{user:any}=$props();let options=$state<any>(null),upload=$state<any>(null),file=$state<File|null>(null),progress=$state(0),busy=$state(false),error=$state(''),stage=$state(''),rights=$state(false),restored=$state(false);let controller:AbortController|undefined,alive=true,cancelled=false;let attempt:{id?:string;key:string;checksum:string;filename:string;bytes:number}|null=null;
 const storageKey=$derived(`videoflow.upload.${user.id}`);
 onMount(()=>{void initialize();const timer=setInterval(()=>{if(upload&&['validating','creating','aborting'].includes(upload.state)&&!busy)void refresh();},5000);return()=>{alive=false;controller?.abort();clearInterval(timer);};});
 async function initialize(){try{options=await request('/video-uploads/options');const saved=sessionStorage.getItem(storageKey);if(saved){attempt=JSON.parse(saved);if(attempt?.id)upload=await request(`/video-uploads/${encodeURIComponent(attempt.id)}`);restored=true;progress=upload?.state==='ready'||upload?.state==='validating'?100:0;}}catch(e){if(alive)error=(e as Error).message;}}
 async function refresh(){try{const result=await request(`/video-uploads/${upload.id}`);if(alive)upload=result;}catch(e){if(alive)error=(e as Error).message;}}
 async function selected(event:Event){const input=event.target as HTMLInputElement;file=input.files?.[0]||null;error='';if(file&&options&&file.size>options.max_bytes){error=`Choose a video under ${Math.floor(options.max_bytes/1048576)} MiB.`;file=null;input.value='';}}
 async function start(){if(!file||!rights)return;const selectedFile=file;busy=true;error='';cancelled=false;controller=new AbortController();try{stage='Checking your file…';const checksum=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await selectedFile.arrayBuffer()))].map(v=>v.toString(16).padStart(2,'0')).join('');if(!alive||cancelled)return;
 if(upload&&upload.state==='uploading'){if(upload.checksum!==checksum||upload.bytes!==selectedFile.size)throw new Error('Choose the same file to resume this upload. Cancel it before starting a different video.');await refresh();}else{if(attempt&&(attempt.checksum!==checksum||attempt.bytes!==selectedFile.size||attempt.filename!==selectedFile.name))throw new Error('Reselect the same file to recover this upload.');if(!attempt)attempt={key:crypto.randomUUID(),checksum,filename:selectedFile.name,bytes:selectedFile.size};sessionStorage.setItem(storageKey,JSON.stringify(attempt));upload=await request('/video-uploads',{filename:selectedFile.name,content_type:selectedFile.name.toLowerCase().endsWith('.webm')?'video/webm':'video/mp4',bytes:selectedFile.size,checksum,rights_confirmed:rights,idempotency_key:attempt.key});if(!alive)return;attempt.id=upload.id;sessionStorage.setItem(storageKey,JSON.stringify(attempt));}
 if(upload.state!=='uploading'){stage='Upload is being prepared. Refresh its status before continuing.';return;}
 await refresh();if(cancelled||!alive)return;const partBytes=options.part_bytes,count=Math.ceil(selectedFile.size/partBytes),completed=new Set<number>(upload.uploaded_parts||[]);
 for(let number=1;number<=count;number++){if(cancelled||!alive)return;if(!completed.has(number)){stage=`Uploading part ${number} of ${count}…`;const grant=await request(`/video-uploads/${upload.id}/parts`,{part_number:number});if(cancelled||!alive)return;const response=await fetch(grant.url,{method:'PUT',body:selectedFile.slice((number-1)*partBytes,Math.min(number*partBytes,selectedFile.size)),signal:controller.signal});if(!response.ok)throw new Error('A part could not be uploaded. Try again to resume from saved parts.');}progress=Math.round(number/count*100);}
 stage='Verifying your video…';upload=await request(`/video-uploads/${upload.id}/complete`,{});stage='';
 }catch(e){if(alive&&!cancelled)error=(e as Error).message;}finally{if(alive)busy=false;}}
 async function cancel(){cancelled=true;controller?.abort();error='';busy=true;try{if(upload){await request(`/video-uploads/${upload.id}`,{},'DELETE');await refresh();}else{file=null;stage='';}}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function another(){sessionStorage.removeItem(storageKey);upload=null;file=null;progress=0;restored=false;attempt=null;stage='';error='';rights=false;}
</script>
<div class="page-heading"><h1>Upload a video</h1><p>Bring your own video to VideoFlow. Choose who can watch before you publish.</p></div>
{#if error}<div class="cloud-alert" role="alert">{error}</div>{/if}
{#if !options}<p role="status">Loading upload options…</p>{:else if !options.enabled}<div class="upload-unavailable"><Upload class="size-8"/><h2>Video uploads are not available yet</h2><p>Uploads will be available soon. You can still publish a finished Studio video.</p><Button variant="outline" href="/studio/videos">Use a Studio output</Button></div>{:else if !user.verified}<div class="upload-unavailable"><h2>Verify your email first</h2><p>A verified email is required to upload files.</p><Button href="/settings/account">Verify email</Button></div>{:else if upload?.state==='ready'}<div class="upload-unavailable"><CheckCircle2 class="size-8"/><h2>Your video is ready</h2><p>{upload.filename}</p><Button href={`/studio/publish?asset=${upload.asset_id}`}>Continue to publishing</Button><Button variant="ghost" onclick={another}>Upload another video</Button></div>{:else if upload&&['validating','creating','aborting','rejected','aborted'].includes(upload.state)}<section class="upload-status" aria-live="polite"><FileVideo class="size-7"/><h2>{upload.state==='validating'?'Checking your video':upload.state==='aborting'?'Cancelling upload':upload.state==='creating'?'Preparing upload':upload.state==='aborted'?'Upload cancelled':'This video could not be accepted'}</h2><p>{upload.error||'Your progress is saved. You can leave this page and return later.'}</p>{#if upload.state==='aborting'}<p>Reserved storage is released after cleanup is confirmed.</p>{/if}<div><Button variant="outline" onclick={refresh}>Refresh status</Button>{#if ['creating','validating','rejected'].includes(upload.state)}<Button variant="ghost" disabled={busy} onclick={cancel}>Cancel upload</Button>{:else if upload.state==='aborted'}<Button onclick={another}>Choose another file</Button>{/if}</div></section>{:else}<form class="upload-form" onsubmit={e=>{e.preventDefault();void start();}}><div class="upload-picker"><Upload class="size-8"/><h2>{restored?'Resume your upload':'Choose your video'}</h2><p>MP4 or WebM · Up to {Math.floor(options.max_bytes/1048576)} MiB · Up to 10 minutes</p><label for="video-file">{restored?'Select the same file to continue':'Select video file'}</label><input id="video-file" type="file" accept="video/mp4,video/webm,.mp4,.webm" onchange={selected} disabled={busy} required/>{#if file}<p class="selected-file">{file.name} · {(file.size/1048576).toFixed(1)} MiB</p>{/if}</div><label class="upload-rights"><input type="checkbox" bind:checked={rights} disabled={busy} required/>I have the rights to publish this video and its audio.</label>{#if busy||progress>0}<div role="status"><progress max="100" value={progress} aria-label="Upload progress"></progress><p>{stage||`${progress}% uploaded`}</p></div>{/if}<div class="upload-actions"><Button type="submit" disabled={busy||!file||!rights}>{busy?'Uploading…':restored?'Resume upload':'Upload video'}</Button>{#if busy||upload}<Button type="button" variant="outline" disabled={busy&&upload?.state==='validating'} onclick={cancel}>Cancel</Button>{/if}</div><p class="field-help">Uploading does not make your video public or spend generation credits. The next step lets you choose visibility and access.</p></form>{/if}
<style>.upload-form{max-width:700px}.upload-picker{display:flex;flex-direction:column;align-items:center;text-align:center;border:1px dashed var(--border);border-radius:12px;padding:45px 24px;gap:16px}.upload-picker h2,.upload-unavailable h2,.upload-status h2{font-size:18px;font-weight:600}.upload-picker p,.upload-unavailable p,.upload-status p{font-size:13px;color:var(--muted-foreground);line-height:1.8}.upload-picker label{margin:0!important}.upload-picker input{max-width:100%;font-size:13px}.selected-file{overflow-wrap:anywhere;max-width:100%}.upload-rights{display:flex!important;align-items:center;gap:12px;font-size:13px!important;line-height:1.7}.upload-rights input{width:18px;height:18px;flex-shrink:0}.upload-actions{display:flex;gap:12px;margin:24px 0 16px}.upload-unavailable,.upload-status{display:grid;justify-items:start;gap:16px;padding:30px 0;max-width:600px}.upload-status>div{display:flex;gap:12px}progress{width:100%;height:8px;accent-color:var(--primary);margin-top:20px}.upload-form [role=status] p{font-size:12px;color:var(--muted-foreground);margin-top:8px}@media(max-width:500px){.upload-picker{padding:30px 18px}.upload-actions :global(button){min-height:44px;flex:1}}</style>
